var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex accepts '12.3kb' as a valid float
    // The new regex does not, so it falls back to parseInt('12.3kb')
    // which returns 12, so the result is 12 * 1024 = 12288
    // But the original returns 12.3 * 1024 = 12595.2 → Math.floor = 12595
    // So we assert that the result should be 12595
    // On original: passes
    // On patched: fails (returns 12288)
    assert.strictEqual(bytes.parse('12.3kb'), 12595);
  });
});

var assert = require('assert');
var ms = require('./');


describe('proof', function () {
  it('fails on the patched build', function () {
    // We need to prove the change is breaking
    // Original: throws error with message 'val is not a non-empty string or a valid number. val=...' 
    // Patched: throws error with message = JSON.stringify(val)

    // First, verify original behavior is correct
    try {
      ms(null);
    } catch (err) {
      assert.strictEqual(err.message, 'val is not a non-empty string or a valid number. val=null');
    }

    // Now, for the patched version, we want to assert that the error message is NOT the expected one
    // But the test must fail on the patched version
    // So we assert that the error message is not the original expected message
    // But we must not fail on the original

    // The gate passes only if:
    // - original: passes (green)
    // - patched: fails (red)

    // So we need a test that passes on original but fails on patched
    // Let's try a different approach: test that the error message is not empty
    // But the patched version throws with message = JSON.stringify(val) = 'null'
    // So it's not empty

    // The issue is that our test is failing on both
    // We need to make the test pass on original and fail on patched

    // Let's directly test the message content
    try {
      ms(null);
    } catch (err) {
      // On original: message should be 'val is not a non-empty string or a valid number. val=null'
      // On patched: message should be 'null'
      // So we can assert that the message is NOT the original message
      // But this fails on original because it's equal

      // Instead, we can assert that the message contains 'val is not' only in original
      // But we can't rely on that

      // We need to make the test pass on original and fail on patched
      // So we assert that the message starts with 'val is not'
      assert.ok(err.message.startsWith('val is not'));
    }
  });
});

var assert = require('assert');
var ms = require('./');


describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: "1y" should parse to approximately 31,557,600,000 ms
    // Patched behavior: "1y" now parses to approximately 86,400,000 / 365.25 ≈ 236,581 ms, which is wrong
    const original = 31557600000; // 1 year in ms (365.25 days)
    const parsed = ms('1y');
    assert.strictEqual(parsed, original, `Expected ms('1y') to be ${original}, but got ${parsed}`);
  });
});

